 "content": "from collections import deque


def transform(grid):
    """Recolor every 4-connected zero component of size >= 2 to 8."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = [[False] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            component = []
            while q:
                y, x = q.popleft()
                component.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 0 and not seen[ny][nx]:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            if len(component) >= 2:
                for y, x in component:
                    out[y][x] = 8
    return out
